#include <WiFi.h>
#include <HTTPClient.h>
#include <ArduinoJson.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

const char* ssid = "NXPLORERS_WIFI";
const char* password = "iotworkshop2026";
const char* serverUrl = "http://192.168.0.100:3001/api/feed";

const int RED_LED = 18;  // ESP32 GPIO 18
const int BUZZER = 19;   // ESP32 GPIO 19

void setup() {
  Serial.begin(115200);
  pinMode(RED_LED, OUTPUT);
  pinMode(BUZZER, OUTPUT);

  Wire.begin(21, 22);
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);

  WiFi.begin(ssid, password);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println("\nWiFi Connected!");
}

void loop() {
  if (WiFi.status() == WL_CONNECTED) {
    HTTPClient http;
    http.begin(serverUrl);
    int httpCode = http.GET();

    if (httpCode == 200) {
      String payload = http.getString();
      StaticJsonDocument<1024> doc;
      deserializeJson(doc, payload);

      JsonObject feed = doc["feeds"][0];
      float temp = feed["field1"] | 0.0;
      float humi = feed["field2"] | 0.0;
      float soil = feed["field4"] | 0.0;

      display.clearDisplay();
      display.setCursor(12, 0);
      display.println("LIVE CLOUD FEED");
      display.setCursor(0, 16);
      display.printf("Temp: %.1f C\n", temp);
      display.printf("Humi: %.1f %%\n", humi);
      display.printf("Soil: %.1f %%\n", soil);

      if (temp > 30.0 || soil < 25.0) {
        digitalWrite(RED_LED, HIGH);
        digitalWrite(BUZZER, HIGH);
        display.setCursor(0, 52);
        display.println("ALERT: HAZARD ACTIVE!");
      } else {
        digitalWrite(RED_LED, LOW);
        digitalWrite(BUZZER, LOW);
        display.setCursor(0, 52);
        display.println("STATUS: SAFE / NORMAL");
      }
      display.display();
    }
    http.end();
  }
  delay(15000);
}
